import { myPayslipsDefs, payrollProcessingDefs } from '../defs/payslips';
import { masterName, type HubConfig } from '../hubEngine';

/**
 * CI employeeMngt/emp_sal_component_mst ("Payroll Processing", admins) and …/paySlip ("My Payslips"): payslips —
 * emp_basic_sal_mst headers of SAL_TYPE PRSTPS with one emp_basic_sal_dtl row per component, generated by
 * Generate Salary (lib/payroll/payslip/*).
 *
 * As CI: Payroll Processing lists the brand's payslips of a month (current employees unless another status is
 * chosen); My Payslips lists only paid payslips — an employee sees their own. Behaviour changes: Income Tax and
 * Incentives / Arrears are real columns (CI's view had no definition for them in any migration); the employee
 * status shows its name (CI printed the id); "All employees" lists every status (CI's My Payslips showed none); a
 * normal user without an employee record sees nothing (CI showed them every paid payslip of every brand); payslips of
 * deleted employees are not listed.
 */
const amount = (column: string) => `to_char(t."${column}", 'FM99999999999999990.00') AS "${column}", t."${column}" AS "${column}_N"`;
const asInt = (column: string, digits: string) => `CASE WHEN t."${column}" ~ '^\\s*[0-9]{${digits}}\\s*$' THEN btrim(t."${column}")::int END`;
const line = (code: string) => `(SELECT to_char(d."ACTUAL_AMOUNT", 'FM99999999999999990.00') FROM emp_basic_sal_dtl d
    WHERE d."SAL_MST_ID" = t."EMP_SAL_ID" AND d."IS_DELETED" = 0
      AND d."SAL_COMP_ID" = (SELECT im."MSTR_ID" FROM independent_mst im WHERE im."MSTR_CD" = '${code}' ORDER BY im."MSTR_ID" LIMIT 1)
    ORDER BY d."EMP_BASIC_SAL_DTL_ID" LIMIT 1)`;

const LIST_COLUMNS = `${amount('ACTUAL_AMOUNT')}, ${amount('EARNED_AMOUNT')},
  CASE WHEN t."TRANSACTION_STATUS" > 0 THEN 'Paid' ELSE 'Unpaid' END AS "TRANSACTION_STATUS", t."TRANSACTION_STATUS" AS "TRANSACTION_STATUS_N",
  t."MONTH", t."YEAR", ${asInt('MONTH', '1,2')} AS "MONTH_N", ${asInt('YEAR', '4')} AS "YEAR_N",
  ${masterName('t."PAY_FREQUENCY_ID"')} AS "PAY_FREQUENCY",
  ${masterName('em."EMP_STATUS_ID"')} AS "EMP_STATUS",
  (SELECT im."MSTR_CD" FROM independent_mst im WHERE im."MSTR_ID" = em."EMP_STATUS_ID" LIMIT 1) AS "EMP_STATUS_CD",
  ${line('SCINTX')} AS "INCOME_TAX", ${line('PCINCARR')} AS "INCENTIVES_ARREARS"`;

export const PAYSLIP_ALIVE = `t."IS_DELETED" = 0 AND t."SAL_TYPE" = (SELECT im."MSTR_ID" FROM independent_mst im WHERE im."MSTR_CD" = 'PRSTPS' ORDER BY im."MSTR_ID" LIMIT 1)`;
const STATUS = /^[A-Z]{2,10}$/;
const MONTH_YEAR = /^(0?[1-9]|1[0-2])\/(\d{4})$/;

const shared = {
  table: 'emp_basic_sal_mst',
  pk: 'EMP_SAL_ID',
  empColumn: 'EMP_ID',
  alive: PAYSLIP_ALIVE,
  listColumns: LIST_COLUMNS,
  search: ['MONTH', 'YEAR', 'PAY_FREQUENCY', 'TRANSACTION_STATUS', 'EMP_STATUS'],
  sorts: ['MONTH_N', 'YEAR_N', 'ACTUAL_AMOUNT_N', 'EARNED_AMOUNT_N', 'TRANSACTION_STATUS_N', 'PAY_FREQUENCY', 'EMP_STATUS'],
  defaultSort: 'v."YEAR_N" DESC NULLS LAST, v."MONTH_N" DESC NULLS LAST, v.id DESC',
  bind: {},
  deleteMode: 'hard' as const,
  noCreate: true,
  noEdit: true,
};

const monthFilter = (q: Record<string, string>, push: (sql: string) => void, p: (v: unknown) => string) => {
  const m = MONTH_YEAR.exec((q.monthYear ?? '').trim());
  if (m) push(`v."MONTH_N" = ${p(Number(m[1]))}::int AND v."YEAR_N" = ${p(Number(m[2]))}::int`);
};

export const payrollProcessingConfig: HubConfig = {
  ...shared,
  key: 'payroll_processing',
  defs: payrollProcessingDefs,
  adminOnlyWrites: true,
  messages: { created: '', updated: '', deleted: 'Successfully Deleted Salary Details' },
  // Deleting a payslip takes back what Generate Salary added (lib/payroll/payslip/delete.ts; loaded lazily — the
  // payroll run imports the hub registry).
  remove: async (tx, ctx) => (await import('@/lib/payroll/payslip/delete')).deletePayslip(tx, ctx),

  // Employment status (current unless chosen; "all"), the payslip month, paid / unpaid.
  listFilter(q, sql) {
    const c: string[] = [];
    const status = (q.status ?? '').trim();
    if (status !== 'all') c.push(`v."EMP_STATUS_CD" = ${sql.p(STATUS.test(status) ? status : 'EMSC')}`);
    monthFilter(q, (s) => c.push(s), (v) => sql.p(v));
    if (q.paid === '1') c.push(`v."TRANSACTION_STATUS_N" > 0`);
    if (q.paid === '0') c.push(`v."TRANSACTION_STATUS_N" = 0`);
    return c.length ? c.join(' AND ') : null;
  },
};

export const myPayslipsConfig: HubConfig = {
  ...shared,
  key: 'my_payslips',
  defs: myPayslipsDefs,
  noDelete: true,
  messages: { created: '', updated: '', deleted: '' },
  // Released (paid) payslips only (CI); an admin's list also filters by employment status (only admins send it).
  listFilter(q, sql) {
    const c = [`v."TRANSACTION_STATUS_N" > 0`];
    const status = (q.status ?? '').trim();
    if (STATUS.test(status)) c.push(`v."EMP_STATUS_CD" = ${sql.p(status)}`);
    monthFilter(q, (s) => c.push(s), (v) => sql.p(v));
    return c.join(' AND ');
  },
};
